import math
import hashlib


def bin_hash(x):
    """Given: the 32-bit hash of x, as a string of '0' and '1'."""
    hash_object = hashlib.sha1(str(x).encode('utf-8'))
    hexa = hash_object.hexdigest()
    bina = bin(int(hexa, 16))[2:].zfill(160)[:32]
    return bina


def constant(b):
    """Given: the constant Const(b) of the estimator."""
    if b == 4:
        return 0.673
    elif b == 5:
        return 0.697
    elif b == 6:
        return 0.709
    else:
        return 0.7213 / (1 + 1.079 / 2 ** b)


